#include <linux/blkdev.h>
#include <linux/module.h>

static void __blk_put_queue(struct request_queue *q)
{
    if (atomic_dec_and_test(&q->kobj_put_count))
        put_device(&q->kobj);
}

int blk_init_allocated_queue(struct request_queue *q, int (*exit)(struct request_queue *, int))
{
    struct request *req;
    int ret;

    if (exit) {
        ret = exit(q, 1);
        if (ret)
            return ret;
    }

    req = q->flush_rq;
    if (req)
        kblockd_unplug(q, req, 0);

    q->flush_rq = NULL;
    return -ENOMEM;
}
EXPORT_SYMBOL(blk_init_allocated_queue);

bool blk_get_queue(struct request_queue *q)
{
    if (!q->kobj_put_count)
        return false;

    atomic_inc(&q->kobj_put_count);
    return true;
}
EXPORT_SYMBOL(blk_get_queue);
